import { state, sports, venues, games, leaderboard, notifications, saveState, resetDemo, bookCourt, cancelBooking, joinGame, leaveGame, hostGame, updateProfile, setColor, setTheme, formatDate, formatMoney, localDate, clubNow } from './data.js';
import { createBandViewer } from './band3d.js';

const paths = {
  home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',
  court:'M3 4h18v16H3zM12 4v16M3 12h18M6 4v16M18 4v16',
  tap:'M12 8a4 4 0 0 1 0 8M15 5a8 8 0 0 1 0 14M18 2a12 12 0 0 1 0 20M5 9h3v6H5z',
  users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  user:'M20 21v-2a7 7 0 0 0-14 0v2M17 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  arrow:'M5 12h14m-6-6 6 6-6 6', chevron:'m9 5 7 7-7 7', chevronDown:'m6 9 6 6 6-6', arrowUp:'M7 17 17 7M7 7h10v10',
  bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4', moon:'M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8', sun:'M12 3V1m0 22v-2M3 12H1m22 0h-2M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',
  pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
  calendar:'M4 5h16v16H4zM4 10h16M8 2v6M16 2v6M8 14h2m4 0h2m-8 3h2', clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',
  trophy:'M8 3h8v7a4 4 0 0 1-8 0zM8 5H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 14v7M8 21h8',
  trend:'m3 17 6-6 4 4 8-10M15 5h6v6', search:'M19 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0m-2 5 5 5',
  close:'m6 6 12 12M6 18 18 6', plus:'M12 5v14M5 12h14', check:'m5 12 4 4L19 6', heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',
  qr:'M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h2v2h-2zM20 14v4h-2v3h-3m6 0h.01',
  edit:'m16 3 5 5M4 16 17 3a3 3 0 0 1 4 4L8 20l-5 1z', shield:'m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7z',
  card:'M3 5h18v14H3zM3 10h18M7 15h3', help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M10 2h4l1 3 3 1 3-1 2 4-2 3 1 3-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-3-1-3 2-4 3 1 3-1z',
  star:'m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9z',
  download:'M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6', copy:'M9 9h12v12H9zM5 15H3V3h12v2', rotate:'M3 10a9 9 0 1 1 1 8M3 4v6h6',
  cube:'m12 3 9 5v8l-9 5-9-5V8zM3 8l9 5 9-5M12 13v8M7 5.8l9 5', play:'m8 5 12 7-12 7z', pause:'M8 5v14M16 5v14',
  sparkle:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z', mail:'M3 5h18v14H3zM3 5l9 7 9-7',
  phone:'M6 3 3 5c0 8 8 16 16 16l2-3-5-4-3 2-5-5 2-3z', list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',
  grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z', lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4M12 14v3',
  racquet:'M19 4c4 4-1 12-6 12-3 0-6-3-6-6 0-5 8-10 12-6M8 15l-5 6M10 5l7 7M7 8l7 7M16 3l-9 9M20 7l-8 8',
  medal:'M8 3 5 8l7 5 7-5-3-5M8 3h8M17 16a5 5 0 1 1-10 0 5 5 0 0 1 10 0',
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.sparkle}"/></svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = (name=state.profile.fullName) => name.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase();
const money = formatMoney;
const $ = selector => document.querySelector(selector);
const modal = $('#modal');
const routes = [ {id:'home',label:'Overview',mobile:'Home',icon:'home'}, {id:'book',label:'Book a court',mobile:'Book',icon:'court'}, {id:'tap',label:'My Zenith Band',mobile:'Tap',icon:'tap'}, {id:'play',label:'Find your people',mobile:'Play',icon:'users'}, {id:'me',label:'My profile',mobile:'Me',icon:'user'} ];
let route = 'home', sportFilter = 'All sports', gameFilter = 'Community', bookDate = localDate(1), query = '', savedOnly = false;
let tapTab = 'band', rankingSport = 'Padel', bookingDraft = null, modalViewer = null, motionPaused = false, toastTimer = null;
let extra;
try { extra = JSON.parse(localStorage.getItem('zenith-demo-extras-v1') || '{}'); } catch { extra = {}; }
extra = {favorites:[],teams:[],tournaments:[],results:[],draft:'', ...extra};
for (const key of ['favorites','teams','tournaments','results']) if (!Array.isArray(extra[key])) extra[key]=[];
extra.favorites=extra.favorites.filter(id=>typeof id==='string'&&venues.some(v=>v.id===id));
extra.teams=extra.teams.filter(t=>t&&typeof t.name==='string'&&sports.includes(t.sport));
extra.results=extra.results.filter(r=>r&&typeof r.opponent==='string'&&typeof r.score==='string');
extra.tournaments=extra.tournaments.filter(id=>typeof id==='string');
if(typeof extra.draft!=='string') extra.draft='';
const persistExtra = () => {try {localStorage.setItem('zenith-demo-extras-v1',JSON.stringify(extra));}catch {toast('This browser cannot save changes after closing.');}};
const bandName = () => state.color === 'cream' ? 'Ivory Clubhouse' : 'Onyx Clubhouse';
const bandImage = () => `assets/band-${state.color}.webp`;
const allGames = () => [...games,...state.hostedGames];
const gameDate = game => game.date || localDate(game.dayOffset);
const venueFor = id => venues.find(v=>v.id===id);
const bookingBy = id => state.bookings.find(b=>b.id===id);
const upcoming = () => state.bookings.filter(b=>b.status==='confirmed' && `${b.date}T${b.time}` > `${clubNow().date}T${clubNow().time}`).sort((a,b)=>`${a.date}${a.time}`.localeCompare(`${b.date}${b.time}`));
const dayLabel = date => date===localDate()?'Today':date===localDate(1)?'Tomorrow':formatDate(date,{weekday:'short'});
const tag = (text, cls='') => `<span class="chip ${cls}">${esc(text)}</span>`;
const empty = (title,copy,action='',label='') => `<div class="empty-state">${icon('sparkle')}<h3>${title}</h3><p>${copy}</p>${action?`<button class="button primary" data-action="${action}">${label}${icon('arrow')}</button>`:''}</div>`;
function toast(text){clearTimeout(toastTimer);$('#toast').innerHTML=`${icon('check')}<span>${esc(text)}</span>`;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function navigate(next){ if(route===next) {render();window.scrollTo({top:0,behavior:'smooth'});} else location.hash=next; }
function applyTheme(){document.documentElement.dataset.theme=state.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.theme; const dark=document.documentElement.dataset.theme==='dark';$('.theme-button').innerHTML=icon(dark?'sun':'moon');$('.theme-button').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} appearance`);document.querySelector('meta[name="theme-color"]').content=dark?'#151c19':'#f7f7f2';}
function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function renderNav(){
  $('#desktop-nav').innerHTML=routes.map(n=>`<a href="#${n.id}" class="nav-item ${route===n.id?'active':''}" ${route===n.id?'aria-current="page"':''}>${icon(n.icon)}<span>${n.label}</span>${n.id==='tap'?'<span class="nav-dot"></span>':''}</a>`).join('')+`<div class="nav-divider"></div><a href="#rankings" class="nav-item ${route==='rankings'?'active':''}" ${route==='rankings'?'aria-current="page"':''}>${icon('trophy')}<span>Club rankings</span></a><a href="#bookings" class="nav-item ${route==='bookings'?'active':''}" ${route==='bookings'?'aria-current="page"':''}>${icon('calendar')}<span>My bookings</span><span class="nav-count">${upcoming().length}</span></a>`;
  $('#mobile-nav').innerHTML=routes.map(n=>`<a href="#${n.id}" class="mobile-nav-item ${n.id==='tap'?'tap-nav':''} ${route===n.id?'active':''}" ${route===n.id?'aria-current="page"':''}><span>${icon(n.icon)}</span><small>${n.mobile}</small></a>`).join('');
  $('#sidebar-name').textContent=state.profile.fullName;$('.sidebar-profile .avatar').textContent=initials();$('.topbar-avatar').textContent=initials();
  $('#route-label').textContent=routes.find(n=>n.id===route)?.label || (route==='rankings'?'Club rankings':'My bookings');
  $('#notification-dot').hidden=state.notificationsRead;
}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subheading">${subtitle}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function avatarStack(players, more=''){return `<div class="avatar-stack">${players.slice(0,3).map(p=>`<span title="${esc(p.name)}" style="--avatar-color:${esc(p.color||'#d9cab4')}">${esc(p.initials||initials(p.name))}</span>`).join('')}${more?`<span class="avatar-more">${esc(more)}</span>`:''}</div>`;}
function colorPicker(){return `<div class="color-picker" role="group" aria-label="Band colour"><button class="swatch black ${state.color==='black'?'selected':''}" data-action="color" data-color="black" aria-label="Onyx black band" aria-pressed="${state.color==='black'}"></button><button class="swatch cream ${state.color==='cream'?'selected':''}" data-action="color" data-color="cream" aria-label="Ivory cream band" aria-pressed="${state.color==='cream'}"></button></div>`;}
function bandHero(){return `<section class="band-hero" aria-label="Your Zenith membership"><div class="hero-copy"><div class="eyebrow">THE ZENITH BAND</div><h2>Your world.<br>A little <em>closer.</em></h2><p>Your people, your courts, your club.<br>All connected by one little band.</p><div class="hero-actions"><button class="button primary" data-action="pass">${icon('qr')}Your member pass${icon('arrow')}</button></div><div class="member-status"><span></span>Club membership <strong>Active · Demo</strong></div></div><div class="hero-band-stage"><div class="band-halo"></div><div class="band-shadow"></div><img class="band-product" src="${bandImage()}" alt="${bandName()} terry wristband with gold embroidered ZC monogram" width="1100" height="1100" fetchpriority="high"><button class="product-view-button" data-action="band-3d">${icon('cube')}Explore in 3D</button></div><div class="band-meta"><div class="band-identity"><span class="tiny-label">YOUR BAND</span><strong class="band-name">${bandName()}</strong></div>${colorPicker()}<span class="band-code">NFC INSIDE ${icon('tap')}</span></div></section>`;}
function stats(){return `<div class="stat-grid"><button class="stat-card" data-action="go" data-route="rankings"><div class="stat-top"><span class="stat-label">ZENITH LEVEL</span>${icon('trend','stat-icon')}</div><div class="stat-bottom"><div class="stat-value">3.8<span> / 7</span></div><svg class="sparkline" viewBox="0 0 110 38" aria-label="Illustrative rising level trend"><path d="M2 32 18 28 28 31 43 19 55 22 68 15 82 17 96 5 108 2" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></div><span class="stat-trend">↗ 0.4 <span>this month</span></span></button><button class="stat-card" data-action="results"><div class="stat-top"><span class="stat-label">MATCHES PLAYED</span>${icon('racquet','stat-icon')}</div><div class="stat-bottom"><div class="stat-value">36<span> matches</span></div><div class="mini-bars" aria-hidden="true">${[28,42,35,60,47,68,83,100].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></div><span class="stat-trend">+8 <span>this month. Keep it going.</span></span></button><button class="stat-card" data-action="go" data-route="me"><div class="stat-top"><span class="stat-label">YOUR WIN RATE</span>${icon('trophy','stat-icon')}</div><div class="stat-bottom"><div class="stat-value">67<span>%</span></div><svg class="mini-ring" viewBox="0 0 50 50" aria-label="67 percent illustrative win rate"><circle cx="25" cy="25" r="20" fill="none" stroke="var(--line)" stroke-width="4"/><circle cx="25" cy="25" r="20" fill="none" stroke="currentColor" stroke-width="4" stroke-dasharray="84 126" transform="rotate(-90 25 25)" stroke-linecap="round"/></svg></div><span class="stat-trend">24 wins <span>and counting</span></span></button></div>`;}
function upcomingCard(){const b=upcoming()[0];const v=b&&venueFor(b.venueId);return `<section class="upcoming-card"><div class="section-top"><h2>Your next match</h2><span class="status-dot"></span></div>${b?`<div class="upcoming-photo"><img src="${v.image}" alt="Illustrative ${v.sport.toLowerCase()} court" width="900" height="600"><span class="sport-tag">${v.sport}</span><span class="photo-credit">DEMO VENUE</span></div><div class="upcoming-content"><div class="eyebrow">${dayLabel(b.date)} · ${b.time}</div><h3>${v.name}</h3><p class="muted">${icon('pin')}${v.area}, Gurugram</p><div class="match-info">${icon('clock')} ${b.duration} min<span>·</span>${b.guests} players</div><div class="booking-footer">${avatarStack([{name:state.profile.fullName,initials:initials(),color:'#dad3c0'},{name:'Anika',initials:'AS',color:'#c8d7ca'},{name:'Aarav',initials:'AM',color:'#e6cfb7'}],'+1')}<button class="text-button" data-action="booking-detail" data-id="${b.id}">View booking ${icon('arrow')}</button></div></div>`:empty('A little room to play.','Your next great match starts with a court.','book-route','Find a court')}</section>`;}
function gameRow(g){const v=venueFor(g.venueId);const joined=state.joinedGames.includes(g.id);return `<div class="game-row"><div class="game-sport-icon">${icon(g.sport==='Padel'?'racquet':'court')}</div><div class="game-row-main"><strong>${esc(g.title)}</strong><span>${esc(v.name)} · ${g.level}</span><div class="game-row-meta">${dayLabel(gameDate(g))}, ${g.time} <span>·</span> ${joined?'You’re in':`${g.spots} spot${g.spots>1?'s':''} open`}</div></div><button class="join-mini ${joined?'joined':''}" data-action="game-detail" data-id="${g.id}" aria-label="View ${esc(g.title)}">${joined?icon('check'):icon('arrowUp')}</button></div>`;}
function home(){const hour=clubNow().hour;const greeting=hour<12?'Good morning':hour<17?'Good afternoon':'Good evening';return heading('YOUR CLUB. YOUR PEOPLE.',`${greeting}, ${esc(state.profile.name)}<span class="heading-star">✦</span>`,'Make a little time for a great game.',`<button class="button secondary" data-action="go" data-route="book">${icon('plus')}Book a court</button>`)+`<div class="home-grid">${bandHero()}${upcomingCard()}</div>${stats()}<div class="dashboard-lower"><section class="panel community-panel"><div class="section-top"><div><div class="eyebrow">BETTER TOGETHER</div><h2>Find your next rally.</h2></div><button class="text-button" data-action="go" data-route="play">See all ${icon('arrow')}</button></div>${games.slice(0,3).map(gameRow).join('')}</section><section class="social-banner"><img src="assets/court-padel.webp" alt="Sunlit green padel court at an illustrative club" loading="lazy"><div class="social-banner-shade"></div><div class="social-banner-content"><span class="light-label">THE CLUB LIFE</span><h2>More than<br><em>a match.</em></h2><p>Good games. New faces.<br>That feeling of belonging.</p><button class="button white" data-action="game-detail" data-id="sunday-social">Explore the weekend social ${icon('arrowUp')}</button></div><span class="social-caption">A LITTLE COMPETITION. A LOT OF CONNECTION.</span></section></div><p class="data-caption">Your activity, rankings and venues are illustrative in this demo.</p>`;}
function sportChips(){return `<div class="filter-row" role="group" aria-label="Filter by sport">${sports.map(s=>`<button class="chip ${sportFilter===s?'active':''}" data-action="sport" data-sport="${s}" aria-pressed="${sportFilter===s}">${s==='All sports'?icon('grid'):''}${s}</button>`).join('')}</div>`;}
function venueCard(v){return `<article class="venue-card"><div class="venue-photo"><img src="${v.image}" alt="Illustrative ${v.sport.toLowerCase()} court at ${v.name}" width="1000" height="650" loading="lazy"><span class="venue-badge">MEMBER RATE · −25%</span><button class="save-venue ${extra.favorites.includes(v.id)?'saved':''}" data-action="save-venue" data-id="${v.id}" aria-label="${extra.favorites.includes(v.id)?'Unsave':'Save'} ${v.name}" aria-pressed="${extra.favorites.includes(v.id)}">${icon('heart')}</button><span class="photo-credit">ILLUSTRATIVE VENUE</span></div><div class="venue-body"><div class="venue-meta"><span>${v.sport}</span><span>${icon('star')} ${v.rating}</span></div><h2>${v.name}</h2><p>${icon('pin')}${v.area} <span>· ${v.distance}</span></p><div class="venue-amenities">${v.amenities.slice(0,3).map(a=>`<span>${a}</span>`).join('')}</div><div class="venue-bottom"><div><span class="price">${money(v.price)}</span><span class="per-hour"> / hr</span><span class="price-old">${money(v.originalPrice)}</span></div><button class="button small primary" data-action="book-venue" data-id="${v.id}">Book ${icon('arrow')}</button></div></div></article>`;}
function dateStrip(){return `<div class="date-strip" role="group" aria-label="Choose booking date">${Array.from({length:8},(_,i)=>{const d=localDate(i);return `<button class="date-button ${d===bookDate?'selected':''}" data-action="book-date" data-date="${d}" aria-pressed="${d===bookDate}"><span>${i===0?'Today':i===1?'Tomorrow':formatDate(d,{weekday:'short',day:undefined,month:undefined})}</span><strong>${Number(d.slice(-2))}</strong><small>${formatDate(d,{day:undefined,month:'short'})}</small></button>`;}).join('')}</div>`;}
function filteredVenues(){return venues.filter(v=>(sportFilter==='All sports'||v.sport===sportFilter)&&(!savedOnly||extra.favorites.includes(v.id))&&`${v.name} ${v.area} ${v.sport}`.toLowerCase().includes(query.toLowerCase()));}
function renderVenueResults(){const list=filteredVenues();$('#venue-results').innerHTML=list.length?list.map(venueCard).join(''):empty('No courts found.','Try another sport or clear your search.','clear-filters','Clear filters');$('#venue-count').textContent=`${list.length} court${list.length===1?'':'s'} to make your own`;}
function book(){const list=filteredVenues();return heading('A LITTLE COURT TIME','Your next great game starts here.','Beautiful courts. Member rates. More reasons to play.')+`<div class="booking-perk">${icon('sparkle')}<span>Your band opens doors. <strong>Enjoy up to 25% off member rates.</strong></span><button class="text-button" data-action="benefits">How it works ${icon('arrow')}</button></div><div class="toolbar"><div class="search-field">${icon('search')}<input type="search" id="court-search" placeholder="Find a court, neighbourhood or sport" value="${esc(query)}" aria-label="Search courts"></div><button class="button secondary ${savedOnly?'is-active':''}" data-action="saved-only" aria-pressed="${savedOnly}">${icon('heart')}Saved courts</button></div>${sportChips()}${dateStrip()}<div class="section-top venue-results-top"><h2 id="venue-count">${list.length} courts to make your own</h2><span class="tiny-label">GURUGRAM · DEMO AVAILABILITY</span></div><div id="venue-results" class="venue-grid">${list.length?list.map(venueCard).join(''):empty('No courts found.','Try another sport or clear your search.','clear-filters','Clear filters')}</div>`;}
function gameCard(g){const v=venueFor(g.venueId);const joined=state.joinedGames.includes(g.id);const hosted=state.hostedGames.some(h=>h.id===g.id);return `<article class="game-card"><div class="game-card-top">${tag(g.sport,'sport-chip')}<span class="game-open-status"><i></i>${hosted?'Hosted by you':joined?'You’re in':`${g.spots} spot${g.spots===1?'':'s'} left`}</span></div><h2>${esc(g.title)}</h2><p class="game-venue">${icon('pin')}${esc(v.name)}<span> · ${esc(g.level)}</span></p><div class="game-card-info"><span>${icon('calendar')}${dayLabel(gameDate(g))}</span><span>${icon('clock')}${g.time} · ${g.duration||90} min</span></div><div class="game-card-bottom">${avatarStack(g.players||[{name:state.profile.fullName,initials:initials()}])}<span class="game-price">${money(g.price||Math.round(v.price/4))}<small>/ player</small></span><button class="button small ${joined?'secondary':'primary'}" data-action="game-detail" data-id="${g.id}">${joined||hosted?'View game':'Join game'}${icon(joined?'check':'arrow')}</button></div></article>`;}
function filteredGames(){return allGames().filter(g=>(sportFilter==='All sports'||g.sport===sportFilter)&&(gameFilter==='Community'||(gameFilter==='My games'&&(state.joinedGames.includes(g.id)||state.hostedGames.some(h=>h.id===g.id)))||(gameFilter==='Friends'&&state.friends.some(f=>(typeof f==='string'?f:f.id)===g.host))));}
function play(){const list=filteredGames();return heading('FIND YOUR PEOPLE','The best games are shared.','Meet your next doubles partner. Or your next good friend.',`<button class="button primary" data-action="host">${icon('plus')}Host a game</button>`)+`<div class="play-feature"><div class="play-feature-icon">${icon('trophy')}</div><div><strong>A little friendly competition.</strong><p>Explore club tournaments and find your next challenge.</p></div><button class="text-button" data-action="tournaments">View tournaments ${icon('arrow')}</button></div><div class="toolbar"><div class="segmented" role="group" aria-label="Game community">${['Community','Friends','My games'].map(t=>`<button class="${gameFilter===t?'active':''}" data-action="game-filter" data-filter="${t}" aria-pressed="${gameFilter===t}">${t}</button>`).join('')}</div><button class="text-button" data-action="friends">${icon('users')}Your circle</button></div>${sportChips()}<div class="section-top"><h2>${gameFilter==='My games'?'Your time on court':'A good game is waiting.'}</h2><span class="muted">${list.length} ${list.length===1?'game':'games'}</span></div><div class="game-grid">${list.length?list.map(gameCard).join(''):empty(gameFilter==='Friends'?'Bring your people together.':'Make the first move.',gameFilter==='Friends'?'Connect with a member to see games hosted by your circle.':'Join a community game or host your own.','host','Host a game')}</div>`;}
function tap(){return heading('WEAR IT. TAP IN. PLAY HIGHER.','Your club, within reach.','One band. A world of connections.',`<button class="button secondary" data-action="pass">${icon('qr')}View member pass</button>`)+`<div class="tap-grid"><section class="panel tap-product-panel"><div class="section-top"><span class="eyebrow">THE ZENITH BAND</span><span class="chip active">Your collection</span></div><div class="tap-stage"><div class="band-halo"></div><div class="band-shadow"></div><img class="band-product" src="${bandImage()}" alt="${bandName()} fabric wristband" width="1100" height="1100"><button class="product-view-button" data-action="band-3d">${icon('cube')}Drag, turn, explore in 3D</button></div><div class="tap-product-bottom"><div><h2 class="band-name">${bandName()}</h2><p>Soft cotton terry. Signature ZC. NFC inside.</p></div>${colorPicker()}</div><div class="band-specs"><span>YOUR DEMO BAND<strong>ZC-DEMO-004</strong></span><span>MEMBERSHIP<strong>Club member</strong></span><span>STATUS<strong class="positive">Active · Demo</strong></span></div></section><section class="panel connect-panel"><div class="eyebrow">A LITTLE CLOSER</div><h2>Make a connection.</h2><p>From a first hello to your next doubles partner.</p><div class="segmented" role="tablist" aria-label="Connection method">${[['band','Band NFC'],['qr','QR code'],['id','Member ID']].map(([k,t])=>`<button role="tab" aria-selected="${tapTab===k}" class="${tapTab===k?'active':''}" data-action="tap-tab" data-tab="${k}">${t}</button>`).join('')}</div><div class="connect-tab-content" role="tabpanel">${tapContent()}</div><div class="demo-note">${icon('help')}Connections in this preview use demo members.</div></section></div><section class="instructions"><div class="step"><span>01</span><div><h3>Wear your club.</h3><p>Your everyday band, on court and beyond.</p></div></div><div class="step"><span>02</span><div><h3>Make the connection.</h3><p>Tap an encoded NFC band with a compatible phone.</p></div></div><div class="step"><span>03</span><div><h3>Take your game higher.</h3><p>Book a court, find a game and make it yours.</p></div></div></section>`;}
function tapContent(){if(tapTab==='qr')return `<div class="qr-preview"><div class="qr-frame" id="tap-qr"></div><h3>Your next hello.</h3><p>Share this demo code with your next doubles partner.</p><button class="button secondary full" data-action="pass">${icon('download')}Open your member pass</button><button class="text-button" data-action="demo-scan">Preview a member scan ${icon('arrow')}</button></div>`;if(tapTab==='id')return `<div class="member-lookup"><div class="lookup-icon">${icon('users')}</div><h3>Find someone from the club.</h3><p>Try demo member <strong>ZC-0008</strong>.</p><form id="member-lookup-form"><label class="form-field"><span>Member ID</span><input name="memberId" placeholder="e.g. ZC-0008" autocomplete="off" maxlength="20" required></label><button class="button primary full" type="submit">Find member ${icon('arrow')}</button><p class="form-error" id="lookup-error" role="status"></p></form></div>`;return `<div class="nfc-experience"><div class="nfc-orbit"><i></i><i></i><span class="nfc-icon">${icon('tap')}</span></div><h3>A simple tap.<br>A new connection.</h3><p>Hold your phone near an encoded band to open its member link.</p><button class="button primary full" data-action="demo-scan">${icon('tap')}Try a demo tap</button><button class="text-button" data-action="nfc-help">How does NFC work? ${icon('arrow')}</button></div>`;}
function me(){const p=state.profile;const menu=[['edit-profile','edit','Edit profile','Make yourself at home.'],['settings','shield','Privacy & appearance','Your experience, your way.'],['friends','users','Friends & requests',`${state.friends.length} people in your circle`],['teams','users','My teams','Better on the same side.'],['tournaments','trophy','Tournaments','Find your next challenge.'],['payments','card','Payments & receipts','Your demo booking history.'],['venue-dashboard','court','Venue overview','Explore the venue-side demo.'],['bookings-route','calendar','My bookings',`${upcoming().length} upcoming sessions`],['results','medal','Results & confirmations','Every match has a story.'],['drafts','edit','Saved drafts','Pick up where you left off.'],['rankings-route','trend','Club rankings','See how the club is playing.']];return heading('YOUR CLUB IDENTITY','This is your game.','Your profile, your progress, your people.',`<button class="button secondary" data-action="edit-profile">${icon('edit')}Edit profile</button>`)+`<div class="profile-grid"><div class="profile-left"><section class="profile-card"><div class="profile-cover"><span class="brand-star">✦</span><span>ZENITH CLUB</span></div><div class="profile-avatar">${esc(initials())}<span>${icon('check')}</span></div><h2>${esc(p.fullName)}</h2><p class="profile-handle">@${esc(p.handle)} · ${esc(p.city)}</p><div class="profile-tags">${tag(p.sport,'sport-chip')}${tag(p.hand)}</div><p class="profile-bio">${esc(p.bio)}</p><div class="profile-stats"><button data-action="friends"><strong>${state.friends.length}</strong><span>Friends</span></button><button data-action="go" data-route="rankings"><strong>#6</strong><span>Club rank</span></button><button data-action="results"><strong>36</strong><span>Matches</span></button></div><button class="button secondary full" data-action="pass">${icon('qr')}Your member pass${icon('arrow')}</button></section><section class="panel playstyle-panel"><div class="eyebrow">YOUR PLAYSTYLE</div><h2>The all-rounder.</h2><p>A steady hand. A competitive heart.</p>${[['Consistency',82],['Net play',74],['Resilience',91]].map(([t,n])=>`<div class="skill-row"><span>${t}</span><div><i style="width:${n}%"></i></div><strong>${n}</strong></div>`).join('')}<span class="tiny-label">ILLUSTRATIVE MATCH INSIGHTS</span></section></div><div><section class="panel profile-membership"><div class="membership-band-thumb"><img src="${bandImage()}" alt="Your ${bandName()} band" width="1100" height="1100"></div><div><div class="eyebrow">YOUR MEMBERSHIP</div><h2 class="band-name">${bandName()}</h2><span class="positive">● Active · Demo member</span></div><button class="icon-button" data-action="go" data-route="tap" aria-label="Manage your band">${icon('arrowUp')}</button></section><div class="menu-list">${menu.map(([a,i,t,d])=>`<button class="menu-item" data-action="${a}">${icon(i)}<span><strong>${t}</strong><small>${d}</small></span>${icon('chevron')}</button>`).join('')}</div></div></div>`;}
function rankings(){return heading('EARNED ON COURT','A little higher, together.','A friendly nudge to keep showing up. Rankings below are demo data.')+`<div class="filter-row">${sports.slice(1).map(s=>`<button class="chip ${rankingSport===s?'active':''}" data-action="ranking-sport" data-sport="${s}" aria-pressed="${rankingSport===s}">${s}</button>`).join('')}</div><section class="panel ranking-panel"><div class="section-top"><h2>${rankingSport} · Club leaderboard</h2><span class="chip">Demo season</span></div><div class="ranking-table" role="table" aria-label="${rankingSport} demo rankings"><div class="ranking-row ranking-header" role="row"><span role="columnheader">RANK</span><span role="columnheader">PLAYER</span><span role="columnheader">LEVEL</span><span role="columnheader">POINTS</span><span role="columnheader">MOVE</span></div>${leaderboard.map((p,i)=>`<div class="ranking-row ${p.name==='Caleb'?'rank-you':''}" role="row"><span class="rank-number" role="cell">${i===0?icon('trophy'):p.rank}</span><span class="ranking-player" role="cell"><span class="avatar small">${p.initials}</span><span>${esc(p.name==='Caleb'?state.profile.fullName:p.name)}${p.name==='Caleb'?'<small>You</small>':''}</span></span><strong role="cell">${p.level.toFixed(1)}</strong><span role="cell">${p.points.toLocaleString()}</span><span class="rank-delta ${p.delta<0?'down':''}" role="cell">${p.delta>0?'↑':p.delta<0?'↓':'—'} ${Math.abs(p.delta)||''}</span></div>`).join('')}</div><p class="demo-note">Rankings in a live club require mutually confirmed match results. This preview does not calculate or publish real ratings.</p></section>`;}
function bookingItem(b){const v=venueFor(b.venueId);return `<article class="booking-item"><img src="${v.image}" alt="Illustrative ${v.sport} court" width="1000" height="650"><div class="booking-item-main"><div class="eyebrow">${v.sport} · ${b.status==='cancelled'?'CANCELLED':'DEMO BOOKING'}</div><h2>${v.name}</h2><p>${icon('calendar')}${formatDate(b.date,{weekday:'short'})} <span>·</span> ${b.time} <span>·</span> ${b.duration} min</p></div><div class="booking-item-price"><strong>${money(b.total)}</strong><small>${b.guests} players</small></div><button class="button secondary small" data-action="booking-detail" data-id="${b.id}">Details ${icon('arrow')}</button></article>`;}
function bookings(){const list=[...state.bookings].sort((a,b)=>`${b.date}${b.time}`.localeCompare(`${a.date}${a.time}`));return heading('MAKE TIME FOR YOUR GAME','Your time on court.','All your upcoming plans, in one good place.',`<button class="button primary" data-action="book-route">${icon('plus')}New booking</button>`)+`<div class="booking-list">${list.length?list.map(bookingItem).join(''):empty('Your calendar is wide open.','Find a court and make your next great game happen.','book-route','Explore courts')}</div><p class="data-caption">These bookings are stored on this device. No real court is reserved and no payment is collected.</p>`;}
function render(){
  const valid=['home','book','tap','play','me','rankings','bookings'];const next=location.hash.slice(1).split('?')[0];route=valid.includes(next)?next:'home';
  renderNav();applyTheme();$('#main').innerHTML=({home,book,tap,play,me,rankings,bookings}[route])();
  if(route==='tap'&&tapTab==='qr') renderQR($('#tap-qr')); document.title=`${$('#route-label').textContent} · Zenith Club`;
}
function closeModal(){modalViewer?.dispose();modalViewer=null;modal.close();document.body.classList.remove('modal-open');}
function openModal(title,content,{wide=false,eyebrow='',footer=''}={}){modalViewer?.dispose();modalViewer=null;$('#modal-body').innerHTML=`<section class="modal-panel ${wide?'wide':''}"><div class="modal-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h2 id="modal-title">${title}</h2></div><button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-content">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section>`;if(!modal.open)modal.showModal();document.body.classList.add('modal-open');}
const demoNote = text=>`<p class="demo-note">${icon('help')}${text||'Demo experience. No real booking or payment is made.'}</p>`;
function renderQR(el){if(!el)return;try{const qr=window.qrcode(0,'M');qr.addData(`${location.origin}${location.pathname}?demo=1#me`);qr.make();el.innerHTML=qr.createSvgTag({cellSize:5,margin:20,scalable:true});el.querySelector('svg').setAttribute('aria-label','QR code opening this demo member experience');el.querySelector('svg').setAttribute('role','img');}catch{el.innerHTML=`${icon('qr')}<p>Use member ID ZC-DEMO-004</p>`;}}
function pass(){openModal('Your club, in your pocket.',`<div class="pass-card"><div class="pass-top"><span>✦ ZENITH CLUB</span>${icon('tap')}</div><div class="pass-info"><small>CLUB MEMBER</small><h3>${esc(state.profile.fullName)}</h3><p>${esc(state.profile.city)} · ${esc(state.profile.sport)}</p></div><div class="pass-qr-wrap"><div class="qr-frame" id="pass-qr"></div></div><div class="pass-bottom"><span>ZC-DEMO-004</span><span>DEMO PASS</span></div></div><div class="pass-actions"><button class="button primary" data-action="download-pass">${icon('download')}Save pass</button><button class="button secondary" data-action="copy-id">${icon('copy')}Copy ID</button></div>${demoNote('This QR opens the demo profile. It is not an access credential or an Apple Wallet pass.')}`,{eyebrow:'YOUR MEMBER PASS'});renderQR($('#pass-qr'));}
function downloadBlob(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.hidden=true;document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(url);},10000);}
function downloadPass(){const qr=$('#pass-qr svg');if(!qr)return;const qrCopy=qr.cloneNode(true);for(const [key,value] of Object.entries({x:'105',y:'210',width:'290',height:'290'}))qrCopy.setAttribute(key,value);const qrMarkup=new XMLSerializer().serializeToString(qrCopy);const content=`<svg xmlns="http://www.w3.org/2000/svg" width="500" height="610" viewBox="0 0 500 610"><rect width="500" height="610" rx="32" fill="#1c2521"/><text x="42" y="62" fill="#dfc39f" font-size="22" font-family="Georgia">✦ ZENITH CLUB</text><text x="42" y="115" fill="#b5baac" font-family="sans-serif" font-size="12">CLUB MEMBER · DEMO</text><text x="42" y="154" fill="#f9f5ea" font-family="Georgia" font-size="28">${esc(state.profile.fullName)}</text>${qrMarkup}<text x="250" y="550" text-anchor="middle" fill="#dfc39f" font-family="sans-serif" font-size="15">ZC-DEMO-004</text><text x="250" y="578" text-anchor="middle" fill="#a7b1a7" font-family="sans-serif" font-size="11">DEMO ONLY · NOT AN ACCESS CREDENTIAL</text></svg>`;downloadBlob(content,'image/svg+xml','zenith-demo-member-pass.svg');toast('Your demo pass is ready to save.');}
async function band3D(){openModal('Every detail. Every angle.',`<div class="interactive-band-wrap"><div id="interactive-band-stage" class="interactive-band-stage"><img class="band-3d-fallback" src="${bandImage()}" alt="${bandName()} product render"></div><div class="viewer-status" id="viewer-status">Preparing your 3D band…</div></div><div class="tap-controls">${colorPicker()}<strong class="band-name">${bandName()}</strong><button class="icon-button" data-action="rotate-toggle" aria-label="Pause automatic motion">${icon('pause')}</button><button class="icon-button" data-action="rotate-reset" aria-label="Reset band view">${icon('rotate')}</button></div><p class="viewer-hint">Drag to turn · Arrow keys to rotate · Crafted from your band references</p>`,{wide:true,eyebrow:'THE ZENITH BAND · 3D STUDIO'});const container=$('#interactive-band-stage');motionPaused=false;const viewer=await createBandViewer(container,{color:state.color,onReady(){const el=$('#viewer-status');if(el)el.textContent='Drag to explore';container.querySelector('img').hidden=true;}});if(!modal.open||!container.isConnected){viewer?.dispose();return;}modalViewer=viewer;if(!viewer){$('#viewer-status').textContent='Product render · 3D is unavailable on this device';$('.viewer-hint').textContent='High-resolution product render · Preview both band colours';$('[data-action="rotate-toggle"]').hidden=true;$('[data-action="rotate-reset"]').hidden=true;}container.addEventListener('band:error',()=>{const img=container.querySelector('img');if(img)img.hidden=false;});}
function bookingForm(id){const v=venueFor(id);if(!v)return;bookingDraft={venueId:id,date:bookDate,time:'',duration:60,guests:4};openModal('Make time for a great game.',`<div class="booking-venue-mini"><img src="${v.image}" alt="Illustrative ${v.sport} court"><div><span class="eyebrow">${v.sport}</span><h3>${v.name}</h3><p>${v.area}, Gurugram</p></div></div><form id="booking-form"><div class="form-grid"><label class="form-field"><span>Date</span><input type="date" name="date" id="reservation-date" min="${localDate()}" value="${bookDate}" required></label><label class="form-field"><span>Session</span><select name="duration" id="reservation-duration"><option value="60">60 minutes</option><option value="90">90 minutes</option><option value="120">120 minutes</option></select></label><label class="form-field"><span>Players</span><select name="guests" id="reservation-guests">${[1,2,3,4].map(n=>`<option value="${n}" ${n===4?'selected':''}>${n} player${n>1?'s':''}</option>`).join('')}</select></label></div><label class="field-label">Choose your time <span>Local club time</span></label><div class="slot-grid" id="reservation-slots"></div><div id="reservation-summary"></div><p class="form-error" id="form-error" role="alert"></p><button class="button primary full" type="submit">Confirm demo booking ${icon('arrow')}</button>${demoNote()}</form>`,{eyebrow:'BOOK A COURT'});updateSlots();updateBookingSummary();}
function updateSlots(){const v=venueFor(bookingDraft.venueId);const minutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3));const date=bookingDraft.date;let selectionAvailable=false;$('#reservation-slots').innerHTML=v.slots.map(t=>{const start=minutes(t),end=start+Number(bookingDraft.duration);const blocked=new Date(`${date}T${t}:00+05:30`)<=new Date()||state.bookings.some(b=>b.status==='confirmed'&&b.venueId===v.id&&b.date===date&&start<minutes(b.time)+Number(b.duration)&&end>minutes(b.time));if(t===bookingDraft.time&&!blocked)selectionAvailable=true;return `<button class="slot-button ${t===bookingDraft.time&&!blocked?'selected':''}" type="button" data-action="select-slot" data-time="${t}" ${blocked?'disabled':''} aria-pressed="${t===bookingDraft.time&&!blocked}">${t}${blocked?'<small>Unavailable</small>':''}</button>`;}).join('');if(!selectionAvailable)bookingDraft.time='';}
function updateBookingSummary(){const v=venueFor(bookingDraft.venueId);const total=v.price*bookingDraft.duration/60;const original=v.originalPrice*bookingDraft.duration/60;$('#reservation-summary').innerHTML=`<div class="booking-summary"><div class="summary-row"><span>Standard court rate</span><span class="price-strike">${money(original)}</span></div><div class="summary-row saving-line"><span>Your member saving</span><span>−${money(original-total)}</span></div><div class="summary-total"><span>Demo total</span><strong>${money(total)}</strong></div><div class="summary-row"><span>${bookingDraft.duration} minutes · ${bookingDraft.guests} players</span><span>${money(total/bookingDraft.guests)} / player</span></div></div>`;}
function bookingDetail(id,confirmed=false){const b=bookingBy(id);if(!b)return;const v=venueFor(b.venueId);openModal(confirmed?'See you on court.':'Your next great game.',`${confirmed?`<div class="confirmation"><div class="confirmation-icon">${icon('check')}</div><h3>Demo booking confirmed.</h3><p>Your court time is on your calendar.</p></div>`:''}<div class="booking-venue-mini"><img src="${v.image}" alt="Illustrative ${v.sport} court"><div><div class="eyebrow">${v.sport}</div><h3>${v.name}</h3><p>${v.area}</p></div></div><div class="booking-summary"><div class="summary-row"><span>Date</span><strong>${formatDate(b.date,{weekday:'long'})}</strong></div><div class="summary-row"><span>Start · Duration</span><strong>${b.time} · ${b.duration} minutes</strong></div><div class="summary-row"><span>Players</span><strong>${b.guests}</strong></div><div class="summary-row"><span>Booking status</span><strong>${b.status==='cancelled'?'Cancelled':'Confirmed · Demo'}</strong></div><div class="summary-total"><span>Demo total</span><strong>${money(b.total)}</strong></div></div>${b.status==='confirmed'?`<div class="pass-actions"><button class="button primary" data-action="calendar" data-id="${b.id}">${icon('calendar')}Add to calendar</button><button class="button secondary" data-action="cancel-booking" data-id="${b.id}">Cancel booking</button></div>`:''}${demoNote('This is a local demo reservation. The venue has not been contacted and no payment was taken.')}`,{eyebrow:`BOOKING · ${esc(b.id.slice(-8).toUpperCase())}`});}
function addCalendar(id){const b=bookingBy(id);const dt=new Date(`${b.date}T${b.time}`);const end=new Date(dt.getTime()+b.duration*60000);const stamp=d=>`${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}${String(d.getMinutes()).padStart(2,'0')}00`;const ics=`BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Zenith Club Demo//EN\r\nBEGIN:VEVENT\r\nUID:${b.id}@zenith-demo\r\nDTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'')}\r\nDTSTART;TZID=Asia/Kolkata:${stamp(dt)}\r\nDTEND;TZID=Asia/Kolkata:${stamp(end)}\r\nSUMMARY:DEMO - ${venueFor(b.venueId).name} ${b.sport}\r\nDESCRIPTION:Demonstration only. No real court has been reserved.\r\nLOCATION:Illustrative venue - Gurugram\r\nSTATUS:TENTATIVE\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n`;downloadBlob(ics,'text/calendar','zenith-demo-booking.ics');toast('Calendar file ready. This event is labelled DEMO.');}
function gameDetail(id){const g=allGames().find(g=>g.id===id);if(!g)return;const v=venueFor(g.venueId);const joined=state.joinedGames.includes(id),hosted=state.hostedGames.some(h=>h.id===id);openModal(esc(g.title),`<div class="game-detail-cover"><img src="${v.image}" alt="Illustrative ${g.sport} court"><span class="sport-tag">${g.sport}</span></div><div class="section-top"><div><h3>${v.name}</h3><p class="muted">${v.area} · ${esc(g.level)}</p></div>${tag(hosted?'Your game':joined?'You’re in':`${g.spots} spots open`,'active')}</div><div class="booking-summary"><div class="summary-row"><span>${icon('calendar')} When</span><strong>${dayLabel(gameDate(g))}, ${g.time}</strong></div><div class="summary-row"><span>Session</span><strong>${g.duration||90} minutes</strong></div><div class="summary-row"><span>Hosted by</span><strong>${esc(g.host)}</strong></div><div class="summary-total"><span>Per player · Demo</span><strong>${money(g.price||Math.round(v.price/4))}</strong></div></div><div class="game-detail-players">${avatarStack(g.players||[])}<span>${hosted?'Invite your circle to your demo game.':'Good people. A good game.'}</span></div>${hosted?`<button class="button secondary full" data-action="copy-game" data-id="${g.id}">${icon('copy')}Copy game details</button>`:`<button class="button ${joined?'secondary':'primary'} full" data-action="${joined?'leave-game':'join-game'}" data-id="${id}">${joined?'Leave demo game':'Count me in'}${icon(joined?'close':'arrow')}</button>`}${demoNote('Joining only updates your demo on this device. It does not send invitations or reserve a real spot.')}`,{eyebrow:'A GOOD GAME. A NEW CONNECTION.'});}
function hostForm(){openModal('Bring the game together.',`<form id="host-form"><label class="form-field"><span>Give your game a name</span><input name="title" placeholder="e.g. A little sunset doubles" required maxlength="70"></label><div class="form-grid"><label class="form-field"><span>Sport</span><select name="sport" id="host-sport">${sports.slice(1).map(s=>`<option>${s}</option>`).join('')}</select></label><label class="form-field"><span>Level</span><select name="level">${['All levels','Beginner','Intermediate','Advanced'].map(l=>`<option>${l}</option>`).join('')}</select></label></div><label class="form-field"><span>Venue</span><select name="venueId" id="host-venue">${venues.filter(v=>v.sport==='Padel').map(v=>`<option value="${v.id}">${v.name}</option>`).join('')}</select></label><div class="form-grid"><label class="form-field"><span>Date</span><input type="date" name="date" min="${localDate()}" value="${localDate(2)}" required></label><label class="form-field"><span>Time</span><select name="time" id="host-time">${venueFor('palm-club').slots.map(t=>`<option ${t==='18:30'?'selected':''}>${t}</option>`).join('')}</select></label><label class="form-field"><span>Open spots</span><select name="spots"><option value="1">1 player</option><option value="2">2 players</option><option value="3" selected>3 players</option></select></label></div><p class="form-error" id="form-error" role="alert"></p><button class="button primary full" type="submit">Create demo game ${icon('arrow')}</button>${demoNote('Your game appears in My games on this device. No real invitations are sent.')}</form>`,{eyebrow:'HOST A GAME'});}
function editProfile(){const p=state.profile;openModal('A little more you.',`<form id="profile-form"><div class="form-grid"><label class="form-field"><span>First name</span><input name="name" value="${esc(p.name)}" maxlength="30" required autocomplete="given-name"></label><label class="form-field"><span>Full name</span><input name="fullName" value="${esc(p.fullName)}" maxlength="70" required autocomplete="name"></label></div><label class="form-field"><span>Club handle</span><input name="handle" value="${esc(p.handle)}" maxlength="24" pattern="[A-Za-z0-9_]+" required></label><div class="form-grid"><label class="form-field"><span>Favourite sport</span><select name="sport">${sports.slice(1).map(s=>`<option ${s===p.sport?'selected':''}>${s}</option>`).join('')}</select></label><label class="form-field"><span>Playing hand</span><select name="hand">${['Right-handed','Left-handed','Ambidextrous'].map(h=>`<option ${h===p.hand?'selected':''}>${h}</option>`).join('')}</select></label></div><label class="form-field"><span>A little about you</span><textarea name="bio" maxlength="240" rows="3">${esc(p.bio)}</textarea></label><p class="form-error" id="form-error" role="alert"></p><button class="button primary full" type="submit">Save profile ${icon('check')}</button>${demoNote('Profile changes stay in this browser. No account is created or updated.')}</form>`,{eyebrow:'EDIT PROFILE'});}
function settings(){openModal('Your experience. Your way.',`<div class="settings-group"><div class="eyebrow">PRIVACY PREFERENCES · DEMO</div>${[['publicProfile','Public profile','Let your club find you.'],['showActivity','Share match activity','Let your circle follow your game.']].map(([key,title,desc])=>`<div class="settings-row"><div><strong>${title}</strong><p>${desc}</p></div><button class="switch ${state.privacy[key]?'on':''}" data-action="privacy" data-key="${key}" role="switch" aria-checked="${state.privacy[key]}" aria-label="${title}"><span></span></button></div>`).join('')}<p class="demo-note">These preferences are saved locally. This demo never publishes your profile or match activity.</p></div><div class="settings-group"><div class="eyebrow">APPEARANCE</div><div class="segmented">${['light','dark','system'].map(t=>`<button class="${state.theme===t?'active':''}" data-action="set-theme" data-theme="${t}" aria-pressed="${state.theme===t}">${t.charAt(0).toUpperCase()+t.slice(1)}</button>`).join('')}</div></div><div class="settings-row"><div><strong>A fresh start.</strong><p>Reset demo bookings, connections and preferences.</p></div><button class="text-button" data-action="reset-confirm">Reset demo</button></div>`,{eyebrow:'SETTINGS'});}
const demoFriends=[{id:'Aarav',name:'Aarav Mehta',initials:'AM',sport:'Padel',level:'4.8'},{id:'Maya',name:'Maya Rao',initials:'MR',sport:'Pickleball',level:'4.3'},{id:'Dev',name:'Dev Malhotra',initials:'DM',sport:'Tennis',level:'4.5'},{id:'Neha',name:'Neha Suri',initials:'NS',sport:'Padel',level:'3.7'}];
function friends(){openModal('Your people, on and off court.',`<p class="muted">A familiar face makes every game better.</p><div>${demoFriends.map(p=>`<div class="friend-row"><span class="avatar">${p.initials}</span><div><strong>${p.name}</strong><p>${p.sport} · Level ${p.level}</p></div><button class="button small ${state.friends.includes(p.id)?'secondary':'primary'}" data-action="friend" data-id="${p.id}">${state.friends.includes(p.id)?icon('check')+'Connected':icon('plus')+'Connect'}</button></div>`).join('')}</div>${demoNote('These are fictional demo members. No friend requests are sent to real people.')}`,{eyebrow:'YOUR CIRCLE'});}
function demoScan(){openModal('A new face. A familiar game.',`<div class="scanned-member"><div class="profile-avatar">AM</div><h3>Aarav Mehta</h3><p>@aarav · Gurugram</p><div class="profile-tags">${tag('Padel','active')}${tag('Level 4.8')}</div><p>Always up for sunset doubles and a good rally.</p><button class="button primary full" data-action="connect-scanned">${icon('users')}${state.friends.includes('Aarav')?'You’re connected':'Add to your circle'}</button></div>${demoNote('Demo member preview. No NFC tag or camera was accessed.')}`,{eyebrow:'DEMO MEMBER FOUND · ZC-0008'});}
function teams(){openModal('Better on the same side.',`${extra.teams.length?extra.teams.map(t=>`<div class="friend-row"><span class="avatar">${esc(initials(t.name))}</span><div><strong>${esc(t.name)}</strong><p>${esc(t.sport)} · You + an open invitation</p></div>${tag('Demo team')}</div>`).join(''):'<p class="muted">Your next doubles partnership starts here. Create a team and make it yours.</p>'}<form id="team-form"><label class="form-field"><span>Team name</span><input name="name" required maxlength="50" placeholder="e.g. The Sunday Rally"></label><label class="form-field"><span>Sport</span><select name="sport">${sports.slice(1).map(s=>`<option>${s}</option>`).join('')}</select></label><button class="button primary full" type="submit">${icon('plus')}Create demo team</button></form>${demoNote('Teams are saved on this device. No invitations are sent.')}`,{eyebrow:'MY TEAMS'});}
function tournaments(){const ts=[{id:'club-open',name:'The Clubhouse Open',sport:'Padel',days:12,format:'Doubles · Intermediate'},{id:'sunday-cup',name:'The Sunday Cup',sport:'Pickleball',days:19,format:'Doubles · All levels'},{id:'baseline-classic',name:'The Baseline Classic',sport:'Tennis',days:25,format:'Singles · Advanced'}];openModal('A little friendly competition.',`${ts.map(t=>`<div class="tournament-row"><div class="tournament-date"><strong>${Number(localDate(t.days).slice(-2))}</strong><span>${formatDate(localDate(t.days),{day:undefined,month:'short'})}</span></div><div><span class="eyebrow">${t.sport}</span><h3>${t.name}</h3><p>${t.format}</p><button class="text-button" data-action="tournament" data-id="${t.id}">${extra.tournaments.includes(t.id)?'Withdraw demo entry':'Join demo waitlist'} ${icon(extra.tournaments.includes(t.id)?'check':'arrow')}</button></div></div>`).join('')}${demoNote('Illustrative events only. There are no real registrations, fees or prizes.')}`,{eyebrow:'CLUB TOURNAMENTS'});}
function payments(){openModal('A clear view of your court time.',`${state.bookings.length?state.bookings.map(b=>`<div class="receipt"><div><strong>${venueFor(b.venueId).name}</strong><p>${formatDate(b.date)} · ${b.status==='cancelled'?'Cancelled':'Demo receipt'}</p></div><span>${money(b.total)}</span><button class="icon-button" data-action="booking-detail" data-id="${b.id}" aria-label="View ${venueFor(b.venueId).name} receipt">${icon('arrowUp')}</button></div>`).join(''):'<p>No demo bookings yet.</p>'}${demoNote('No money has moved. Payment collection, deposits and refunds require a live payment provider.')}`,{eyebrow:'PAYMENTS & RECEIPTS'});}
function results(){openModal('Every match has a story.',`${extra.results.length?extra.results.map(r=>`<div class="receipt"><div><strong>${esc(r.opponent)}</strong><p>${esc(r.sport)} · ${esc(r.score)}</p></div>${tag('Awaiting confirmation')}</div>`).join(''):''}<form id="result-form"><label class="form-field"><span>Demo opponent</span><input name="opponent" value="Aarav Mehta" required maxlength="60"></label><div class="form-grid"><label class="form-field"><span>Sport</span><select name="sport">${sports.slice(1).map(s=>`<option>${s}</option>`).join('')}</select></label><label class="form-field"><span>Set scores</span><input name="score" placeholder="6-4, 6-3" required pattern="[0-9 ,:-]+" maxlength="40"></label></div><button class="button primary full" type="submit">Submit demo result ${icon('arrow')}</button></form>${demoNote('Results stay pending in this demo. No opponent is notified and no real ranking is changed.')}`,{eyebrow:'RESULTS & CONFIRMATIONS'});}
function drafts(){openModal('Pick up where you left off.',`<form id="draft-form"><label class="form-field"><span>Your match note</span><textarea name="draft" rows="7" maxlength="2000" placeholder="A thought about your last match, or a plan for your next one…">${esc(extra.draft)}</textarea></label><button class="button primary full" type="submit">Save draft ${icon('check')}</button></form>${demoNote('Only saved on this device. Your note is never published.')}`,{eyebrow:'SAVED DRAFTS'});}
function venueDashboard(){openModal('A view from the other side.',`<div class="notice">Venue operator preview · Illustrative activity</div><div class="mini-stat-grid"><div><span>Court occupancy</span><strong>72%</strong></div><div><span>Sessions today</span><strong>18</strong></div><div><span>Member share</span><strong>64%</strong></div></div><h3>The Palm Club · Today</h3><div class="venue-timeline">${['07:00','08:30','10:00','12:00','15:00','16:30','18:30','20:00'].map((t,i)=>`<div><span>${t}</span><strong class="${i===3||i===4?'available':''}">${i===3||i===4?'Available':'Demo reservation'}</strong></div>`).join('')}</div>${demoNote('This dashboard is a sample view. It has no administrative access to any venue.')}`,{eyebrow:'VENUE OVERVIEW'});}
function notify(){state.notificationsRead=true;saveState();$('#notification-dot').hidden=true;openModal('A little news from your club.',`${notifications.map(n=>`<div class="notification-item"><span class="notification-symbol">${icon(n.id==='welcome'?'sparkle':n.id==='match-ready'?'calendar':'trophy')}</span><div><strong>${n.title}</strong><p>${n.body}</p><small>${n.time}</small></div></div>`).join('')}<button class="button secondary full" data-action="close-modal">All caught up ${icon('check')}</button>`,{eyebrow:'NOTIFICATIONS · DEMO'});}
function help(){openModal('We’re one tap away.',`<p class="modal-lead">Good people behind a great club.</p><p>For the real Zenith Club, use their public contact details below.</p><a class="contact-link" href="mailto:zenithclubcompany@gmail.com">${icon('mail')}<span>Email Zenith<strong>zenithclubcompany@gmail.com</strong></span>${icon('arrowUp')}</a><a class="contact-link" href="https://www.zenithclub.online/" target="_blank" rel="noopener noreferrer">${icon('sparkle')}<span>The original club<strong>zenithclub.online</strong></span>${icon('arrowUp')}</a><a class="contact-link" href="https://www.instagram.com/zenithclub.co/" target="_blank" rel="noopener noreferrer">${icon('users')}<span>On Instagram<strong>@zenithclub.co</strong></span>${icon('arrowUp')}</a>${demoNote('This redesigned experience is a standalone demo. Original accounts, orders and support remain with Zenith Club.')}`,{eyebrow:'CLUB CONCIERGE'});}
function about(){openModal('A new view of Zenith.',`<div class="about-mark">✦</div><p class="modal-lead">Your club. Your people.<br>Your next great game.</p><p>A redesigned member experience inspired by Zenith’s identity, with a quiet, considered interface and a little product magic.</p><div class="about-details"><p><strong>Ready to explore</strong><br>Courts, games, profiles, band colours, a real 3D viewer, a demo QR pass and local bookings.</p><p><strong>Made for demonstration</strong><br>Venues, members, ratings, activity and prices are illustrative. Changes stay in your browser. No payments, real reservations or messages are sent.</p><p><strong>Your real club stays separate</strong><br>This preview does not connect to Zenith’s authentication, membership records or NFC access system.</p></div>`,{eyebrow:'ZENITH CLUB · MEMBER EXPERIENCE'});}
async function copyText(text,message){try{await navigator.clipboard.writeText(text);toast(message);}catch{openModal('Copy your details.',`<textarea class="copy-text" readonly>${esc(text)}</textarea><p class="muted">Select and copy the text above.</p>`);}}

document.addEventListener('click',async e=>{
  const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,id=button.dataset.id;
  try {
    switch(a){
      case 'go':closeModal();navigate(button.dataset.route);break;
      case 'book-route':closeModal();navigate('book');break;
      case 'bookings-route':closeModal();navigate('bookings');break;
      case 'rankings-route':closeModal();navigate('rankings');break;
      case 'close-modal':closeModal();break;
      case 'pass':pass();break;
      case 'download-pass':downloadPass();break;
      case 'copy-id':await copyText('ZC-DEMO-004','Demo member ID copied.');break;
      case 'band-3d':await band3D();break;
      case 'color':setColor(button.dataset.color);document.querySelectorAll('.band-name').forEach(el=>el.textContent=bandName());document.querySelectorAll('.band-product,.band-3d-fallback,.membership-band-thumb img').forEach(el=>{el.src=bandImage();el.alt=`${bandName()} terry wristband`;});document.querySelectorAll('.swatch').forEach(el=>{el.classList.toggle('selected',el.dataset.color===state.color);el.setAttribute('aria-pressed',el.dataset.color===state.color);});modalViewer?.setColor(state.color);break;
      case 'rotate-toggle':motionPaused=!motionPaused;modalViewer?.setAutoRotate(!motionPaused);button.innerHTML=icon(motionPaused?'play':'pause');button.setAttribute('aria-label',motionPaused?'Resume automatic motion':'Pause automatic motion');break;
      case 'rotate-reset':modalViewer?.reset();break;
      case 'theme':setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');applyTheme();break;
      case 'set-theme':setTheme(button.dataset.theme);applyTheme();settings();break;
      case 'notifications':notify();break;
      case 'sport':sportFilter=button.dataset.sport;render();break;
      case 'ranking-sport':rankingSport=button.dataset.sport;render();break;
      case 'game-filter':gameFilter=button.dataset.filter;render();break;
      case 'book-date':bookDate=button.dataset.date;render();break;
      case 'saved-only':savedOnly=!savedOnly;render();break;
      case 'clear-filters':sportFilter='All sports';savedOnly=false;query='';render();break;
      case 'save-venue':extra.favorites=extra.favorites.includes(id)?extra.favorites.filter(i=>i!==id):[...extra.favorites,id];persistExtra();renderVenueResults();break;
      case 'book-venue':bookingForm(id);break;
      case 'select-slot':bookingDraft.time=button.dataset.time;updateSlots();break;
      case 'booking-detail':bookingDetail(id);break;
      case 'calendar':addCalendar(id);break;
      case 'cancel-booking':openModal('Free up your court time?',`<p>This cancels the local demo reservation. You can book another session at any time.</p><div class="pass-actions"><button class="button primary" data-action="confirm-cancel" data-id="${id}">Cancel demo booking</button><button class="button secondary" data-action="booking-detail" data-id="${id}">Keep booking</button></div>`,{eyebrow:'YOUR BOOKING'});break;
      case 'confirm-cancel':cancelBooking(id);render();bookingDetail(id);toast('Demo booking cancelled.');break;
      case 'game-detail':gameDetail(id);break;
      case 'join-game':joinGame(id);render();gameDetail(id);toast('You’re in. A good game is waiting.');break;
      case 'leave-game':leaveGame(id);render();gameDetail(id);toast('You’ve left this demo game.');break;
      case 'copy-game':{const g=allGames().find(g=>g.id===id);await copyText(`Zenith demo game: ${g.title}\n${venueFor(g.venueId).name}\n${gameDate(g)} at ${g.time}\nDemonstration only. No real venue reserved.`,'Demo game details copied.');break;}
      case 'host':hostForm();break;
      case 'tap-tab':tapTab=button.dataset.tab;render();break;
      case 'demo-scan':demoScan();break;
      case 'connect-scanned':if(!state.friends.includes('Aarav')){state.friends.push('Aarav');saveState();}render();demoScan();toast('Aarav is in your demo circle.');break;
      case 'friend':state.friends=state.friends.includes(id)?state.friends.filter(i=>i!==id):[...state.friends,id];saveState();render();friends();break;
      case 'friends':friends();break;
      case 'edit-profile':editProfile();break;
      case 'settings':settings();break;
      case 'privacy':state.privacy[button.dataset.key]=!state.privacy[button.dataset.key];saveState();settings();break;
      case 'teams':teams();break;
      case 'tournaments':tournaments();break;
      case 'tournament':extra.tournaments=extra.tournaments.includes(id)?extra.tournaments.filter(i=>i!==id):[...extra.tournaments,id];persistExtra();tournaments();toast('Your demo entry has been updated.');break;
      case 'payments':payments();break;
      case 'results':results();break;
      case 'drafts':drafts();break;
      case 'venue-dashboard':venueDashboard();break;
      case 'help':help();break;
      case 'about':about();break;
      case 'location':openModal('Your club is in Gurugram.',`<div class="location-illustration">${icon('pin')}</div><p class="modal-lead">One city. Many courts.<br>A whole new circle.</p><p>This demo explores Gurugram. Venue names, distances and availability are illustrative; your device location is never requested.</p>`,{eyebrow:'YOUR LOCAL CLUB'});break;
      case 'benefits':openModal('A little more court time.',`<div class="benefit-number">25<span>%</span></div><p class="modal-lead">Member rates.<br>Every reason to play.</p><p>The original Zenith member app describes partner-court discounts of up to 25%. This preview shows illustrative member prices alongside standard rates, with savings calculated before you book.</p>${demoNote('Live partner availability and discounts must be confirmed with Zenith.')}`,{eyebrow:'YOUR CLUB BENEFITS'});break;
      case 'nfc-help':openModal('One tap connects the dots.',`<div class="nfc-icon">${icon('tap')}</div><div class="instructions vertical"><div class="step"><span>01</span><div><h3>Find the NFC point.</h3><p>Hold the NFC reader area of your compatible phone close to the chip inside the band.</p></div></div><div class="step"><span>02</span><div><h3>Open the notification.</h3><p>An encoded web link can open the member experience. Device support and tag setup vary.</p></div></div><div class="step"><span>03</span><div><h3>Connect through your club.</h3><p>The live service must verify the member separately. A band ID alone is not a secure login.</p></div></div></div>${demoNote('This preview simulates the tap flow. It does not read, write or authenticate NFC tags.')}`,{eyebrow:'TAP. SYNC. RANK.'});break;
      case 'reset-confirm':openModal('Ready for a fresh start?',`<p>Reset this demo’s bookings, profile edits, saved courts, games and preferences on this device.</p><button class="button primary full" data-action="reset">Reset the demo</button>`);break;
      case 'reset':resetDemo();extra={favorites:[],teams:[],tournaments:[],results:[],draft:''};persistExtra();closeModal();render();toast('A fresh start. Welcome back to Zenith.');break;
    }
  }catch(error){toast(error.message||'Something went wrong. Please try again.');}
});
document.addEventListener('input',e=>{if(e.target.id==='court-search'){query=e.target.value;renderVenueResults();}});
document.addEventListener('change',e=>{
  if(e.target.id==='reservation-date'){bookingDraft.date=e.target.value;updateSlots();}
  if(e.target.id==='reservation-duration'){bookingDraft.duration=Number(e.target.value);updateSlots();updateBookingSummary();}
  if(e.target.id==='reservation-guests'){bookingDraft.guests=Number(e.target.value);updateBookingSummary();}
  if(e.target.id==='host-sport'){$('#host-venue').innerHTML=venues.filter(v=>v.sport===e.target.value).map(v=>`<option value="${v.id}">${v.name}</option>`).join('');$('#host-time').innerHTML=venueFor($('#host-venue').value).slots.map(t=>`<option>${t}</option>`).join('');}
  if(e.target.id==='host-venue')$('#host-time').innerHTML=venueFor(e.target.value).slots.map(t=>`<option>${t}</option>`).join('');
});
document.addEventListener('submit',e=>{
  const id=e.target.id;if(!['booking-form','host-form','profile-form','member-lookup-form','team-form','result-form','draft-form'].includes(id))return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));
  try{
    if(id==='booking-form'){if(!bookingDraft.time)throw new Error('Choose an available time for your game.');const b=bookCourt(bookingDraft);bookDate=bookingDraft.date;render();bookingDetail(b.id,true);}
    if(id==='host-form'){const g=hostGame({...data,spots:Number(data.spots)});gameFilter='My games';sportFilter='All sports';render();gameDetail(g.id);toast('Your demo game is ready.');}
    if(id==='profile-form'){updateProfile(data);closeModal();render();toast('Looking good. Your profile is updated.');}
    if(id==='member-lookup-form'){if(data.memberId.trim().toUpperCase()==='ZC-0008')demoScan();else if(data.memberId.trim().toUpperCase()==='ZC-DEMO-004')pass();else{$('#lookup-error').textContent='No demo member found. Try ZC-0008.';}}
    if(id==='team-form'){if(!data.name.trim())throw new Error('Give your team a name.');extra.teams.push({name:data.name.trim(),sport:data.sport,id:Date.now()});persistExtra();teams();toast('Your demo team is ready.');}
    if(id==='result-form'){extra.results.push({...data,status:'pending',id:Date.now()});persistExtra();results();toast('Demo result saved. Awaiting confirmation.');}
    if(id==='draft-form'){extra.draft=data.draft;persistExtra();closeModal();toast('Draft saved. Pick it up whenever you’re ready.');}
  }catch(error){const output=$('#form-error');if(output)output.textContent=error.message;else toast(error.message);}
});
modal.addEventListener('click',e=>{if(e.target===modal){const rect=$('#modal-body').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
modal.addEventListener('close',()=>{modalViewer?.dispose();modalViewer=null;document.body.classList.remove('modal-open');});
modal.addEventListener('cancel',()=>{modalViewer?.dispose();modalViewer=null;document.body.classList.remove('modal-open');});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.theme==='system')applyTheme();});
$('.help-link').innerHTML=`${icon('help')}<span>Club concierge</span>${icon('arrowUp')}`;
hydrateIcons();render();
